def simulate(g):
    H,W=len(g),len(g[0])
    out=[r[:] for r in g]
    sr,sc=next((r,c) for r in range(H) for c in range(W) if g[r][c]==2)
    has_band_rows = any(sum(1 for v in g[r] if v==8)>=W//2 for r in range(H))
    N = W if has_band_rows else H
    bands=[r for r in range(H) if sum(1 for v in g[r] if v==8)>=W//2] if has_band_rows else \
          [c for c in range(W) if sum(1 for r in range(H) if g[r][c]==8)>=H//2]
    def gaps_of(b):
        return [k for k in range(N) if (g[b][k]==0 if has_band_rows else g[k][b]==0)]
    opened=set(); entry=sc if has_band_rows else sr
    for i,br in enumerate(bands):
        gaps=gaps_of(br)
        last=(i==len(bands)-1)
        lo,hi=spread_extent(entry,gaps,opened,N-1)
        if has_band_rows:
            for c in range(lo,hi+1): out[br-1][c]=2
        else:
            for r in range(lo,hi+1): out[r][br-1]=2
        cand=[k for k in (lo,hi) if k in gaps and k!=entry]
        if not cand:
            cand=[k for k in gaps if lo<=k<=hi and k in opened and k!=entry]
        if not cand: break
        main=min(cand,key=lambda k:(abs(k-entry),k))
        opened.add(main)
        if last:
            if has_band_rows:
                for r in range(br,H): out[r][main]=2
            else:
                for c in range(br,W): out[main][c]=2
            break
        nb=bands[i+1]
        ngaps=gaps_of(nb)
        nlo,nhi=spread_extent(main,ngaps,opened,N-1)
        falls=[main]+[x for x in cand if x!=main and nlo<=x<=nhi]
        for k in falls:
            if has_band_rows:
                for r in range(br,nb): out[r][k]=2
            else:
                for c in range(br,nb): out[k][c]=2
        entry=main
    return out

